      "body": "2019 年修正少年事件處理法，乃為呼應司法院釋字第 664 號解釋及兒童權利公約保護兒童及少年之意旨，縮減原有曝險事由範圍且去除其虞犯之身分標籤，改以關注其是否處於犯罪邊緣而曝露於危險之中事由，而有調整保護必要作為是否由司法介入條件，並以「曝險少年」稱之，且繼而建置少年輔導委員會行政輔導先行機制。試論述少年輔導委員會在處理曝險少年時，應兼具之主要角色功能為何？（25 分）",
