          "prompt": "甲於網路上販售一款宣稱有減肥功效的軟糖，有些消費者反映食用後身體不適，甲仍繼續販賣。在朋友乙推薦下，丙購買一盒放置在客廳茶几上。某日，丙外出，委託乙照顧丙 6 歲兒子 A。在乙未注意下，A 大量食用該軟糖。A 食用後逐漸出現呼吸困難與抽搐等急性中毒症狀。乙見此狀，因害怕被追究責任迅速離去。數小時後，丙回家發現 A 倒臥在地，緊急送醫後，A 仍不治死亡。法醫鑑定表示，依據現有醫學證據，若能即時給予適當醫療處置，A 死亡結果發生的風險將顯著降低。試依據中華民國刑法之規定分析甲、乙前述行為可能涉及的刑事責任。（25 分）",
