          "prompt": "甲遇紅燈停車，遭後方未保持適當距離之乙騎摩托車撞上，甲車並無大礙，但乙因車輛倒地雙腿擦挫傷，路人 A 見狀迅速打電話叫警察及救護車，甲認為不是自己之問題，且為了趕上班，心想乙已有人救助，未等待警方到場處理，並未獲得乙同意，也未留下日後可供聯繫之資料，即逕自離開現場。警察 B 到場後聞到乙滿身酒氣，測得其呼氣酒測值為0.23，又見其無法走直線，語無倫次，遂移送地檢署。B 根據路人拍攝涉嫌甲之車牌後循線找到甲之住處，甲不在家，甲妻丙以為甲闖禍，向 B表示當天開車者是她，B 遂將丙移送地檢署。試問甲、乙、丙之行為依刑法如何評價？（25 分）",
