          "prompt": "甲酒駕經緩起訴處分確定後，某夜，眾多酒友為其設宴慶祝，宴畢，甲自認飲酒已作節制，雖有微酣感但應不致超標，遂不聽友人勸告駕車上路。途中，逢大雨視線不良，甲因專心於察看有無酒測攔檢致疏未開啟車前大燈，對向駕車之乙急於返家超速疾駛（速限 70 公里／小時，乙車速逾 1 百公里），由於路面多處嚴重積水，乙車打滑失控衝過雙黃線而闖入甲車車道，甲來不及反應之際兩車已然對撞。乙當場死亡，甲則重傷於駕駛座上，經警員酒測，甲吐氣所含之酒精濃度為每公升 0.35 毫克。試問：甲上述之酒駕肇事行為應如何處斷？（本案有關車輛之沒收與否無須討論）（25 分）",
