          "title": "原題回想",
          "prompt": "甲因涉嫌重傷害未遂罪，經檢察官提起公訴。法院以甲罹有「思覺失調症」以及「酒精使用障礙症」，於實施犯罪行為時，確已因精神障礙致不能辨識其行為違法或欠缺依其辨識而行為之能力，依刑法第 19 條第 1 項規定，應屬不罰，而為無罪之諭知。又經評估後，法院以被告甲為預防被告未來因精神疾病影響而再為類似犯行，並避免因其疾病而對個人、家庭及社會造成難以預期之危害，且能使其獲得適當之治療處遇，並依刑法第 87 條第 1 項、第 3 項前段，刑事訴訟法第 301 條第 2 項規定，裁定令入相當處所，施以監護 4 年，以收個人治療及社會防衛之效。俟裁定確定後，檢察官送當地醫院執行。請論述：（25 分）（一）我國刑法在「刑罰」之外，另設有「保安處分」，請說明保安處分之設置目的、主要內容及功能為何？（二）甲因本案於裁判確定前受羈押日數共 175 天，是否可折抵監護處分日數？",
